{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio measured as number of students divided by number of (full-time equivalent) teachers in the district. Primary independent variable; higher values mean more students per teacher (larger class sizes).",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "District-level academic performance measured as the average of the 5th-grade reading and math Stanford-9 scores.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district average). Controls for financial resources.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average income (in USD 1,000). Controls for socio-economic status.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent of students qualifying for CalWorks (income assistance). Controls for poverty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Percent of students qualifying for reduced-price lunch. Controls for poverty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent of English learners. Controls for language composition which can affect test scores.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Computers per student (number of computers divided by number of students). Controls for technology resources.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputersPerStudent"
        ]
      },
      {
        "description": "Log of total students (log1p). Controls for district size / scale effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "LogStudents"
        ]
      },
      {
        "description": "Grade span of the district (KK-06 vs KK-08). Included as a categorical fixed effect to control for organizational differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "grades"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure numeric columns are numeric (coerce errors to NaN)\n    numeric_cols = ['students', 'teachers', 'read', 'math', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'computer']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows missing the primary variables needed to compute the key measures\n    df = df.dropna(subset=['students', 'teachers', 'read', 'math'])\n\n    # Exclude rows with non-positive teacher counts to avoid division by zero\n    df = df[df['teachers'] > 0]\n\n    # Compute student-teacher ratio (students per teacher)\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Dependent variable: average of reading and math\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Computers per student (may be small); guard against division issues\n    df['ComputersPerStudent'] = df['computer'] / df['students']\n    df['ComputersPerStudent'].replace([np.inf, -np.inf], np.nan, inplace=True)\n\n    # Size control: log of students (use log1p to handle small counts safely)\n    df['LogStudents'] = np.log1p(df['students'])\n\n    # Ensure categorical control is a category dtype\n    if 'grades' in df.columns:\n        df['grades'] = df['grades'].astype('category')\n\n    # Drop rows with NA in controls that will be used in the model to keep the same sample across regressors\n    required_for_model = ['StudentTeacherRatio', 'AvgScore', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'ComputersPerStudent', 'LogStudents', 'grades']\n    # Only include those required columns that are present in df\n    required_present = [c for c in required_for_model if c in df.columns]\n    df = df.dropna(subset=required_present)\n\n    # Final returned dataframe contains original columns plus derived columns used in modeling\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    import statsmodels.formula.api as smf\n\n    # Define formula: effect of student-teacher ratio on average score controlling for resources and demographics\n    formula = (\n        'AvgScore ~ StudentTeacherRatio + expenditure + income + calworks + lunch + english '\n        '+ ComputersPerStudent + LogStudents + C(grades)'\n    )\n\n    # Fit OLS with robust (heteroskedasticity-consistent) standard errors\n    model = smf.ols(formula, data=df).fit(cov_type='HC3')\n\n    # Return the fitted results object for inspection (summary, params, conf_int, etc.)\n    return model\n"
}

{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio calculated as total students divided by full-time-equivalent teachers. This is the independent variable; lower values indicate fewer students per teacher.",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "Average academic performance in the district: mean of the Stanford-9 reading and math scores (5th grade). This is the dependent variable.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district resources).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average income (in thousands USD) — control for socioeconomic status.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent qualifying for CalWorks (income assistance) — proxy for poverty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Percent qualifying for reduced-price lunch — proxy for low-income student share.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent of English learners — control for language-related academic challenges.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Computers per student (computer divided by students) — proxy for technology resources.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "ComputerPerStudent"
        ]
      },
      {
        "description": "Log of total enrollment (controls for district scale and nonlinearity of size effects).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "LogStudents"
        ]
      },
      {
        "description": "Dummy for grade span KK-08 (1 if grades == 'KK-08', 0 if 'KK-06' or other) — controls structural differences.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Grades_KK08"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure numeric columns are numeric where appropriate\n    numeric_cols = ['students', 'teachers', 'computer', 'expenditure', 'income', 'calworks', 'lunch', 'english', 'read', 'math']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Remove rows with missing critical values: students, teachers, read, math\n    req = ['students', 'teachers', 'read', 'math']\n    df = df.dropna(subset=req)\n\n    # Remove unrealistic teacher counts (<= 0) to avoid division by zero\n    df = df[df['teachers'] > 0]\n\n    # Dependent variable: average of reading and math scores\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Independent variable: student-teacher ratio (students per teacher)\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Control: computers per student (avoid divide-by-zero; students > 0 ensured above)\n    df['ComputerPerStudent'] = df['computer'] / df['students']\n\n    # Log enrollment (use natural log); guard against nonpositive students\n    df['LogStudents'] = np.log(df['students'].astype(float))\n\n    # Grade-span dummy: 1 if KK-08, 0 otherwise (including KK-06)\n    if 'grades' in df.columns:\n        df['Grades_KK08'] = (df['grades'].astype(str) == 'KK-08').astype(int)\n    else:\n        df['Grades_KK08'] = 0\n\n    # Keep columns needed for modeling plus originals for context\n    needed_cols = [\n        'AvgScore', 'StudentTeacherRatio', 'expenditure', 'income', 'calworks', 'lunch', 'english',\n        'ComputerPerStudent', 'LogStudents', 'Grades_KK08'\n    ]\n\n    # If any control columns are missing in the input dataset, create them as NaN to keep consistent schema\n    for col in needed_cols:\n        if col not in df.columns:\n            df[col] = np.nan\n\n    # Drop rows with missing values in any of the model columns\n    df = df.dropna(subset=needed_cols)\n\n    # Reset index\n    df = df.reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    # Build design matrix\n    model_cols = [\n        'StudentTeacherRatio',\n        'expenditure',\n        'income',\n        'calworks',\n        'lunch',\n        'english',\n        'ComputerPerStudent',\n        'LogStudents',\n        'Grades_KK08'\n    ]\n\n    X = df[model_cols].astype(float)\n    X = sm.add_constant(X)\n    y = df['AvgScore'].astype(float)\n\n    # Fit OLS with robust (HC1) standard errors\n    ols_model = sm.OLS(y, X).fit(cov_type='HC1')\n\n    # Return the fitted results object. Caller can print summary via print(ols_model.summary())\n    return ols_model\n"
}
